SELECT jsonb_build_object('read13_marker','RuntimeReservation/positive/B'::text,'position','BEFORE'::text);
SELECT jsonb_build_object('model','RuntimeCommandReceipt','ids',coalesce(jsonb_agg(observed.id::text ORDER BY observed.id::text COLLATE "C"),'[]'::jsonb)) FROM (SELECT id,owner_module_id,operation,subject_scope,semantic_key,fingerprint,state,source_revision,result_schema_id,result_schema_version,result_digest,result_body,created_at,mutation_transaction_id FROM platform.runtime_command_receipt WHERE id IN ('6d1b5813-44bc-5ece-9c35-db327f128bd7'::uuid)) observed;
SELECT jsonb_build_object('model','RuntimeReservation','ids',coalesce(jsonb_agg(observed.id::text ORDER BY observed.id::text COLLATE "C"),'[]'::jsonb)) FROM (SELECT id,command_receipt_id,owner_module_id,resource_kind,resource_key,semantic_key,quantity,state,fence,effect_receipt_id,expires_at,created_at,mutation_transaction_id FROM platform.runtime_reservation WHERE id IN ('570f8ca0-0d41-5478-bd07-c1c145304abf'::uuid,'ca735678-2cbb-56ff-ae43-2afe000df153'::uuid)) observed;
SET CONSTRAINTS ALL IMMEDIATE;
SELECT jsonb_build_object('read13_marker','RuntimeReservation/positive/B'::text,'position','AFTER'::text);
